//! Compare scripted priority scan against all twelve retained original rows.
use spore_core::cell_provider_priority_scan_v1::{project,Node};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native stdout")).unwrap();assert_eq!(b.len(),192);for i in 0..12{let k=i%6;let cw=if i>=6{0x37f}else{0x27f};let mut nodes=[Node{key:0x12345678,value:11,priority:1},Node{key:0x12345678,value:22,priority:2}];match k{0=>nodes[0].key=0x99999999,2=>nodes[1].priority=1,3=>nodes[0].priority=-1,4=>nodes[1].priority=-1,5=>nodes[1].key=0x99999999,_=>{}}let result=project(0x12345678,&nodes,cw,0x1f80,true).unwrap().unwrap_or(0);let row=&b[i*16..(i+1)*16];assert_eq!(w(row,0),result);assert_eq!(w(row,4),i as u32);let fp=w(row,8);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,12)&!0x3f,0x1f80);}println!("matched 12 retained priority rows; synthetic stable links and lifetimes admitted");}
